var scene=new Scene();try{CameraComponent camera;ModelRenderer background;ModelRenderer spray;using(scene.Push()){var sky=new GameObject(true,"Probe light").Components.Create<DirectionalLight>();sky.LightColor=new Color(.6f,.65f,.7f);sky.SkyColor=new Color(.3f,.3f,.3f);sky.Shadows=false;var b=new GameObject(true,"Opaque depth receiver");b.WorldPosition=new Vector3(3260,-430,100);background=b.Components.Create<ModelRenderer>();background.Model=Model.Cube;var bs=background.Model.Bounds.Size;b.WorldScale=new Vector3(40/bs.x,400/bs.y,400/bs.z);background.MaterialOverride=Material.Load("materials/forestbase/rubber.vmat");var s=new GameObject(true,"Installed impact mist");s.WorldPosition=new Vector3(3200,-430,100);s.WorldRotation=Rotation.LookAt(Vector3.Up,new Vector3(-1,0,0));spray=s.Components.Create<ModelRenderer>();spray.Model=Model.Plane;var size=spray.Model.Bounds.Size;s.WorldScale=new Vector3(280/size.x,280/size.y,1);spray.MaterialOverride=Material.Load("materials/forestbase/waterfall_spray.vmat");var c=new GameObject(true,"Probe camera");camera=c.Components.Create<CameraComponent>();camera.WorldPosition=new Vector3(3000,-430,100);camera.WorldRotation=Rotation.LookAt(new Vector3(3200,-430,100)-camera.WorldPosition);camera.FieldOfView=65;camera.BackgroundColor=Color.Black;scene.EditorTick(.016f,.016f);}await Task.Delay(800,cancellationToken);var files=new System.Collections.Generic.List<object>();foreach(var phase in new[]{"motion0","motion1","soft10","hard10"}){using(scene.Push()){if(phase=="soft10")background.WorldPosition=new Vector3(3230,-430,100);if(phase=="hard10"){var control=spray.MaterialOverride.CreateCopy("mist-control-no-depth-feather");control.Set("MistDepthFeather",0f);spray.MaterialOverride=control;}using var bitmap=new Bitmap(640,640);scene.EditorTick(.016f,.016f);camera.RenderToBitmap(bitmap,false);var file=System.IO.Path.Combine(exchangeDirectory,"mist-probe-"+phase+".png");System.IO.File.WriteAllBytes(file,bitmap.ToPng());files.Add(new{Phase=phase